// ============================================================================
// 【B-1】Framer Orbit — 可上架元件(breathe-right preset;副線,與 Cover Flow
// 平行)
//
// 目標(照 FRAMER-PUBLISH.md SOP + CoverflowSpike 前例):圖片能傳、參數策展
// 收斂、拖進來就是 breathe-right 的樣子、會自動播放、可拖曳。單一模板(orbit)。
//
// 引擎:computeCardTransforms 原樣內聯自 src/templates/orbit/orbitMath.js 的
// 【4-arg 版】(config, tPos, tAmb, dragVel)。數學已對照真引擎逐位元驗過
// (見附帶 orbit-parity 測,含 6 個開放參數值域掃描 max Δ=0)。
//
// ⚠️【DOM 透視鏈忠實】層數與 app 一致、不精簡(對照 OrbitTemplate.jsx + app.css
//    的 .tpl-scene/.tpl-offset/.tpl-group/.tpl-card):
//   design(方形 1080²,overflow:hidden,contain 縮放置中 —— 見下方【響應式】)
//   └ scene(abs,inset:0,perspective:1000px ← 容器級透視,非 per-card)
//     └ offset(abs,inset:0,preserve-3d,translate offsetX/Y)
//       └ group(abs,inset:0,preserve-3d,rotateX/Y/Z + scale(zoom/100))
//         └ card(abs,left:50%,top:50%,overflow:hidden)
//           └ img(100%×100%,object-fit:cover)
//   per-card 每幀(逐字抄自 OrbitTemplate.jsx 的 render):
//     el.style.transform = `translate(-50%,-50%) translate3d(x,y,z)`
//       + (rotateY?) + (rotateX?) + (rotateZ(rotation)?) + ` scale(scale)`
//   breathe-right 下 rotateX/rotateY 恆 0(tilt 鎖 0),rotateZ 為 jitter 的
//   rotationDrift(≠0);照 app 條件式省略 0 項。
//
// 策展:開放 8 個 property controls —— Cards(圖片槽)/ count / cardSize /
//   cardRatio / cornerRadius / duration / zoom / draggable。其餘全部鎖死為
//   breathe-right preset 的值(見 LOCKED)。
//
//   ⚠️ 與 Cover Flow 相異處(逐項理由見完工回報):
//   1. 透視是【容器級】(scene 的 perspective),非 Cover Flow 的 per-card
//      perspective() —— orbit 的環狀 3D 需 .tpl-group 保 preserve-3d
//      (Cover Flow 覆寫為 flat)。
//   2. 響應式用【固定 1080² 方形設計畫布 + contain 置中】,非 Cover Flow 的
//      自動 aspect 填滿 —— orbit 是放射狀,量測 breathe-right 實際佔幅
//      ~802×844px(< 1080² 有餘裕、不裁),方形 contain 完全等於 app 1:1 的
//      原樣臉;非方形 frame 兩側留透明邊(放射狀的正確行為,焦點卡永不裁)。
//   3. cornerRadius 改為【直接 px】(對齊 Cover Flow 前例、買家直覺),非 orbit
//      schema 的「min(邊)×%」語意。預設 14px ≈ breathe-right 6% 的視覺等值。
//   4. motion 鎖【continuous】→ baseAngleFor 的 step 分支不可達、省略(免拉
//      gsap.parseEase);放手慣性只走 continuous 的 runMomentum。
//   5. tilt(tiltX/Y/Z)與 orient 鎖 0 → computeCardTransforms 的 tilt/orient
//      區塊零貢獻、省略(對鎖定 config 逐位元等值,見 parity 測)。
// ============================================================================

import {
    useCallback,
    useEffect,
    useLayoutEffect,
    useMemo,
    useRef,
    useState,
} from "react"
// Standalone Framer Shim for Next.js / React
const useIsStaticRenderer = () => false;
const addPropertyControls = () => {};
const ControlType = {
    Boolean: 'boolean', Number: 'number', String: 'string',
    Color: 'color', Enum: 'enum', Object: 'object',
    Array: 'array', Image: 'image', ResponsiveImage: 'responsiveImage',
    Font: 'font', Transition: 'transition', Link: 'link'
};


// ----------------------------------------------------------------------
// 常數 —— 原樣抄自 orbitMath.js / noise.js(同名同值)。
// ----------------------------------------------------------------------
// Hand-tuned feel parameter (orbitMath.js): fade/scale falloff exponent.
const FALLOFF_EXPONENT = 3
// noise.js: golden angle, decorrelates seeds across octaves.
const GOLDEN_ANGLE = 2.399963

// 固定方形設計畫布(對齊 app PreviewCanvas 的 1:1 設計解析度 1080²)。
const DESIGN = 1080

// breathe-right preset 的【性格骨架】—— 不開放,鎖死。開放的由 props 覆蓋。
// 逐值抄自 src/templates/orbit/presets.js 的 orbit-breathe-right.config
// (orient 該 preset 省略 → 繼承 schema 預設 0;tiltX/Y/Z 0)。
const LOCKED = {
    orbitRadius: 380,
    planeX: 0,
    planeZ: -45,
    orient: 0,
    direction: "forward" as const,
    motion: "continuous" as const,
    cycles: 1,
    jitterAmount: 16,
    jitterSpeed: 0.5,
    rotationDrift: 10,
    fade: 100,
    scale: 10,
    perspective: 1000,
    // Framing(zoom 開放,其餘鎖 0):
    rotationX: 0,
    rotationY: 0,
    rotationZ: 0,
    offsetX: 0,
    offsetY: 0,
    // tilt 鎖 0(velocity-driven lean 關閉):
    tiltX: 0,
    tiltY: 0,
    tiltZ: 0,
}

const lerp = (a: number, b: number, t: number) => a + (b - a) * t
const wrapTime = (t: number, d: number) => ((t % d) + d) % d

// --- noise.js 逐字內聯(jitter 用;breathe-right jitterAmount 16 + rotationDrift 10 皆 active)---
function loopNoise(
    phase: number,
    seed: number,
    octaves: { freq: number; amp: number }[]
): number {
    let v = 0
    let ampSum = 0
    for (const { freq, amp } of octaves) {
        v +=
            amp *
            Math.sin(
                2 * Math.PI * (freq * phase) + seed * (freq + 1) * GOLDEN_ANGLE
            )
        ampSum += amp
    }
    return v / ampSum
}
function jitterOctaves(speed: number): { freq: number; amp: number }[] {
    const f = Math.max(1, Math.round(speed))
    return [
        { freq: f, amp: 1.0 },
        { freq: f * 2, amp: 0.5 },
        { freq: f * 3, amp: 0.25 },
    ]
}

interface OrbitConfig {
    count: number
    orbitRadius: number
    duration: number
    fade: number
    scale: number
    planeX: number
    planeZ: number
    orient: number
    jitterAmount: number
    jitterSpeed: number
    rotationDrift: number
    cycles: number
    direction: "forward" | "reverse"
    motion: "continuous" | "step"
    // for the DOM (not the math):
    cardSize: number
    cardRatio: string
    cornerRadius: number
}

interface CardTransform {
    x: number
    y: number
    z: number
    rotateX: number
    rotateY: number
    rotation: number
    scale: number
    opacity: number
    zIndex: number
}

// --- 原樣抄自 orbitMath.js ---
// motion 鎖 continuous → 只保留 continuous 分支(step 分支不可達、省略:見檔頭
// 相異處 #4)。continuous 完全不碰 ease,故無 gsap.parseEase 依賴。dragVel 在
// continuous 下不影響 baseAngle(對齊 orbitMath:step&&dragVel===0 才進 step 分支)。
function baseAngleFor(config: OrbitConfig, t: number): number {
    const { cycles, duration, direction } = config
    const dirSign = direction === "reverse" ? -1 : 1
    return dirSign * cycles * 360 * (t / duration)
}

// 抄自 orbitMath.js:轉的是【位置向量】不是卡片朝向(billboarding 不變)。
function applyPlaneTilt(
    x0: number,
    z0: number,
    planeXRad: number,
    planeZRad: number
) {
    const y1 = -z0 * Math.sin(planeXRad)
    const z1 = z0 * Math.cos(planeXRad)
    const x2 = x0 * Math.cos(planeZRad) - y1 * Math.sin(planeZRad)
    const y2 = x0 * Math.sin(planeZRad) + y1 * Math.cos(planeZRad)
    return { x: x2, y: y2, z: z1 }
}

// 【4-arg 版,原樣內聯自 orbitMath.js】對鎖定 config 逐位元等值:
//   - motion continuous → baseAngleFor 走 continuous(見上)。
//   - tiltX/Y/Z 鎖 0 → tiltActive false → tilt 區塊零貢獻、省略(dragVel 因此
//     在本元件對輸出無影響 —— 仍保留於簽章供 parity 測逐位元對照)。
//   - orient 鎖 0 → orientActive false → orient 區塊零貢獻、省略。
// jitter(active)、plane(planeZ=-45 active)、falloff、scale/opacity、zIndex 逐字未改。
function computeCardTransforms(
    config: OrbitConfig,
    tPos: number,
    tAmb: number = tPos,
    _dragVel: number = 0
): CardTransform[] {
    const {
        count,
        orbitRadius,
        duration,
        fade,
        scale,
        planeX,
        planeZ,
        orient,
        jitterAmount,
        jitterSpeed,
        rotationDrift,
    } = config

    const jitterActive = jitterAmount > 0 || rotationDrift > 0
    const octaves = jitterActive ? jitterOctaves(jitterSpeed) : null
    const phase = tAmb / duration

    const planeActive = planeX !== 0 || planeZ !== 0
    const planeXRad = (planeX * Math.PI) / 180
    const planeZRad = (planeZ * Math.PI) / 180

    const orientActive = orient > 0

    const baseAngle = baseAngleFor(config, tPos)

    const transforms: CardTransform[] = []
    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (i * 360) / count
        const rad = (angle * Math.PI) / 180
        const x0 = Math.sin(rad) * orbitRadius
        const z0 = Math.cos(rad) * orbitRadius

        let x: number, y: number, z: number
        if (planeActive) {
            const p = applyPlaneTilt(x0, z0, planeXRad, planeZRad)
            x = p.x
            y = p.y
            z = p.z
        } else {
            x = x0
            y = 0
            z = z0
        }

        const depth = (z / orbitRadius + 1) / 2
        const curved = Math.pow(depth, FALLOFF_EXPONENT)

        let rotation = 0
        if (jitterActive && octaves) {
            x += jitterAmount * loopNoise(phase, (i + 1) * 17.31, octaves)
            y += jitterAmount * loopNoise(phase, (i + 1) * 29.17, octaves)
            rotation =
                rotationDrift * loopNoise(phase, (i + 1) * 43.77, octaves)
        }

        // tilt 區塊省略(tiltX/Y/Z 鎖 0)—— 見上。
        if (orientActive) {
            rotation += (orient / 100) * angle
        }

        transforms.push({
            x,
            y,
            z,
            rotateX: 0,
            rotateY: 0,
            rotation,
            scale: lerp(scale / 100, 1, curved),
            opacity: lerp(fade / 100, 1, curved),
            zIndex: Math.round(depth * 1000),
        })
    }
    return transforms
}

// ----------------------------------------------------------------------
// 預設示範圖 v2(做法 B fallback)—— Su 定稿的 7 張出貨 demo(demo-photos-v2/
// final/,暖橘同卷 grade + 文案卡),取代初版街拍。slot 順序照檔名排
// (panel-1..6),第 4 槽固定為色塊卡 block-1(環轉節奏重拍位)。各降至 640px
// 寬、cwebp q82、base64 內嵌 —— 元件自包含(單檔可貼、不掛外部 URL)。買家沒
// 上傳 → 顯示這 7 張(i % n 循環,對齊 app assets[i % assets.length]);有上傳
// → 用買家的。舊街拍組經 git 歷史可回溯。
const DEMO_IMAGES: string[] = [
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
]

/**
 * @framerIntrinsicWidth 600
 * @framerIntrinsicHeight 600
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */
export default function OrbitSpike(props: {
    images: string[]
    count: number
    cardSize: number
    cardRatio: string
    cornerRadius: number
    duration: number
    zoom: number
    draggable: boolean
}) {
    const {
        images,
        count,
        cardSize,
        cardRatio,
        cornerRadius,
        duration,
        zoom,
        draggable,
    } = props

    // 做法 B:有圖用買家的(濾掉空槽);沒有 → fallback 內建預設示範圖。
    const provided = (Array.isArray(images) ? images : []).filter(Boolean)
    const effectiveImages = provided.length > 0 ? provided : DEMO_IMAGES

    const poolSize = Math.max(0, Math.floor(count))

    const rootRef = useRef<HTMLDivElement>(null)
    const cardRefs = useRef<(HTMLDivElement | null)[]>([])
    const configRef = useRef<OrbitConfig | null>(null)
    // drive 狀態跨 re-render 持續(對齊 app gsap timeline 的 preserve-progress)。
    const driveRef = useRef({
        offset: 0,
        extraRate: 0,
        tPos: 0,
        tAmb: 0,
        playing: true,
        isDragging: false,
        lastX: 0,
        lastMoveTime: 0,
        lastRate: 0,
        clockLast: 0,
    })
    const [frame, setFrame] = useState({ w: 600, h: 600 })

    useLayoutEffect(() => {
        const el = rootRef.current
        if (!el) return
        const observer = new ResizeObserver(([entry]) => {
            setFrame({
                w: entry.contentRect.width,
                h: entry.contentRect.height,
            })
        })
        observer.observe(el)
        return () => observer.disconnect()
    }, [])

    const config: OrbitConfig = useMemo(
        () => ({
            ...LOCKED,
            count: poolSize,
            duration,
            cardSize,
            cardRatio,
            cornerRadius,
        }),
        [poolSize, duration, cardSize, cardRatio, cornerRadius]
    )
    configRef.current = config // driver 每幀讀最新 config(對齊 app configRef)

    // 卡片尺寸:cardSize 為寬,ratio(W:H)導出高。
    const [ratioW, ratioH] = cardRatio.split(":").map(Number)
    const cardHeight = cardSize * (ratioH / ratioW)
    // Corner Radius 為【直接 px】(相異處 #3),上限 clamp 到卡片較短邊的一半。
    const cardRadius = Math.min(
        cornerRadius,
        Math.min(cardSize, cardHeight) / 2
    )

    // 【響應式】固定方形設計畫布 contain 置中(相異處 #2):fitScale =
    // min(frameW, frameH) / DESIGN —— 方形畫布縮到 frame 短邊、置中;非方形 frame
    // 兩側留透明邊。與 app 1:1(1080² overflow:hidden)逐像素同一渲染面。
    const fitScale = Math.min(frame.w / DESIGN, frame.h / DESIGN)

    // 靜態渲染(Framer 畫布編輯態 + 匯出/thumbnail)凍結 t=0 單幀 —— useIsStaticRenderer
    // 涵蓋畫布編輯 + export(審核要求)。只有真實 Preview / 發布後(false)才動、才可拖。
    const isStatic = useIsStaticRenderer()

    const paint = useCallback(
        (cfg: OrbitConfig, tPos: number, tAmb: number, dragVel: number) => {
            const transforms = computeCardTransforms(cfg, tPos, tAmb, dragVel)
            transforms.forEach((tr, i) => {
                const el = cardRefs.current[i]
                if (!el) return
                el.style.transform =
                    `translate(-50%, -50%) translate3d(${tr.x}px, ${tr.y}px, ${tr.z}px)` +
                    (tr.rotateY ? ` rotateY(${tr.rotateY}deg)` : "") +
                    (tr.rotateX ? ` rotateX(${tr.rotateX}deg)` : "") +
                    (tr.rotation ? ` rotateZ(${tr.rotation}deg)` : "") +
                    ` scale(${tr.scale})`
                el.style.opacity = String(tr.opacity)
                el.style.zIndex = String(tr.zIndex)
            })
        },
        []
    )

    // 靜態單幀(畫布編輯態 + 匯出):凍結 t=0。
    useEffect(() => {
        if (!(isStatic || poolSize === 0)) return
        paint(config, 0, 0, 0)
    }, [config, isStatic, poolSize, paint])

    // Preview / 發布:主 render/clock 迴圈 + drag/scroll driver。常數/公式/衰減曲線
    // 一律【逐字抄自】useTimelineInteraction.js(app)與 CoverflowSpike 已審核的
    // vanilla 版。deps 不含 config —— driver 讀 configRef 最新值、drive 狀態存
    // driveRef,故 config 變不重置 tAmb(對齊 app preserve-progress)。
    useEffect(() => {
        if (isStatic || poolSize === 0) return
        const root = rootRef.current
        if (!root) return
        const d = driveRef.current
        d.isDragging = false
        d.clockLast = performance.now()
        if (!draggable) {
            d.playing = true
            d.offset = 0
            d.extraRate = 0
        }

        // ---- 常數:逐字抄自 useTimelineInteraction.js ----
        const IDLE_MS = 50
        const MAX_FLICK_ITEMS = 10
        const SENSITIVITY = 100
        const MOMENTUM = 50
        const FLICK_MIN_DURATION = 0.3
        const FLICK_MAX_DURATION = 2.2
        const DECAY_K_MULTIPLIER = 3
        const CONTINUOUS_DECAY_EPS = 0.015
        const STEP_DECAY_EPS = 0.04
        const getCoastT = (coastDuration: number, eps: number) =>
            -Math.log(eps) / (DECAY_K_MULTIPLIER / coastDuration)
        const rateAtElapsed = (
            amplitude: number,
            elapsed: number,
            coastDuration: number
        ) =>
            amplitude *
            Math.exp(-(DECAY_K_MULTIPLIER / coastDuration) * elapsed)
        const solveAmplitudeForDistance = (
            distance: number,
            coastDuration: number,
            eps: number
        ) => (distance * (DECAY_K_MULTIPLIER / coastDuration)) / (1 - eps)
        const sensitivityMult = Math.pow(2, (SENSITIVITY - 50) / 50)
        // orbit「一格 Δt」= duration/(cycles×count)(getOneItemDeltaT else 分支;
        // orbit 用 config.count)。deltaTPerPx 逐字抄自 app,讀最新 config。
        const oneItemDelta = () => {
            const c = configRef.current!
            return c.duration / (c.cycles * c.count)
        }
        const deltaTPerPx = () => {
            const c = configRef.current!
            return c.cardSize > 0
                ? (oneItemDelta() / c.cardSize) * sensitivityMult
                : 0
        }

        let raf = 0
        let releaseRaf = 0
        let idleRaf = 0
        let wheelTimer: ReturnType<typeof setTimeout> | 0 = 0

        const stopRelease = () => {
            if (releaseRaf) {
                cancelAnimationFrame(releaseRaf)
                releaseRaf = 0
            }
        }
        const settleRelease = () => {
            d.extraRate = 0
            d.playing = true // 元件恆 resume(無 play/pause 鈕);onRelease≡'resume'
        }
        const rebaseToGrid = (targetTPos: number) => {
            d.tAmb = wrapTime(targetTPos, configRef.current!.duration)
            d.offset = 0
        }

        // continuous 放手:runMomentum(breathe-right motion 鎖 continuous → 恆走此路)。
        const runMomentum = (initialRate: number) => {
            stopRelease()
            const coastDuration =
                FLICK_MIN_DURATION +
                (MOMENTUM / 100) * (FLICK_MAX_DURATION - FLICK_MIN_DURATION)
            const coastT = getCoastT(coastDuration, CONTINUOUS_DECAY_EPS)
            const start = performance.now()
            let last = start
            const step = (now: number) => {
                const dt = Math.min((now - last) / 1000, 0.05)
                last = now
                const elapsed = (now - start) / 1000
                if (elapsed >= coastT) {
                    settleRelease()
                    releaseRaf = 0
                    return
                }
                const rate = rateAtElapsed(initialRate, elapsed, coastDuration)
                d.offset += rate * dt
                d.extraRate = rate
                releaseRaf = requestAnimationFrame(step)
            }
            releaseRaf = requestAnimationFrame(step)
        }
        // step 放手(runFlick):motion 鎖 continuous → 不可達;保留為忠實 port
        // (與 CoverflowSpike 同構),handleRelease 恆走 runMomentum。
        const runFlick = (currentTPos: number, initialRate: number) => {
            stopRelease()
            const c = configRef.current!
            const coastDuration =
                FLICK_MIN_DURATION +
                (MOMENTUM / 100) * (FLICK_MAX_DURATION - FLICK_MIN_DURATION)
            const item = oneItemDelta()
            const dirSignLocal = c.direction === "reverse" ? -1 : 1
            const naturalDistance = (initialRate * coastDuration) / 3
            const maxDistance = item * MAX_FLICK_ITEMS
            const clampedDistance = Math.max(
                -maxDistance,
                Math.min(maxDistance, naturalDistance)
            )
            const naturalTarget = currentTPos + dirSignLocal * clampedDistance
            const snapTarget =
                item > 0
                    ? Math.round(naturalTarget / item) * item
                    : naturalTarget
            const fromOffset = d.offset
            const toOffset =
                fromOffset + dirSignLocal * (snapTarget - currentTPos)
            const coastT = getCoastT(coastDuration, STEP_DECAY_EPS)
            const amplitude = solveAmplitudeForDistance(
                toOffset - fromOffset,
                coastDuration,
                STEP_DECAY_EPS
            )
            const start = performance.now()
            let last = start
            const step = (now: number) => {
                const dt = Math.min((now - last) / 1000, 0.05)
                last = now
                const elapsed = (now - start) / 1000
                if (elapsed >= coastT) {
                    rebaseToGrid(snapTarget)
                    settleRelease()
                    releaseRaf = 0
                    return
                }
                const rate = rateAtElapsed(amplitude, elapsed, coastDuration)
                d.offset += rate * dt
                d.extraRate = rate
                releaseRaf = requestAnimationFrame(step)
            }
            releaseRaf = requestAnimationFrame(step)
        }
        const handleRelease = (initialRate: number) => {
            if (configRef.current!.motion === "step")
                runFlick(d.tPos, initialRate)
            else runMomentum(initialRate)
        }
        const watchIdle = () => {
            if (!d.isDragging) {
                idleRaf = 0
                return
            }
            if (performance.now() - d.lastMoveTime > IDLE_MS) {
                d.extraRate = 0
                d.lastRate = 0
            }
            idleRaf = requestAnimationFrame(watchIdle)
        }

        // 主 render/clock 迴圈。tPos/tAmb/dragVel 組合逐字抄自
        // useCardTransformTimeline.js / OrbitTemplate.jsx 的 render。
        const tick = (now: number) => {
            const c = configRef.current!
            const dur = c.duration
            const dirSign = c.direction === "reverse" ? -1 : 1
            const dt = Math.min((now - d.clockLast) / 1000, 0.05)
            d.clockLast = now
            if (d.playing) d.tAmb = wrapTime(d.tAmb + dt, dur)
            const ambRate = d.playing ? 1 : 0
            const dragVel = ambRate + dirSign * d.extraRate - 1
            d.tPos = wrapTime(d.tAmb + dirSign * d.offset, dur)
            paint(c, d.tPos, d.tAmb, dragVel)
            raf = requestAnimationFrame(tick)
        }
        raf = requestAnimationFrame(tick)

        // ---- 事件層(僅 draggable 時綁定)----
        let removeDown: (() => void) | null = null
        let removeWheel: (() => void) | null = null
        let endInFlight: (() => void) | null = null
        if (draggable) {
            const onPointerDown = (e: PointerEvent) => {
                stopRelease()
                d.isDragging = true
                d.playing = false
                d.lastX = e.clientX
                d.lastMoveTime = performance.now()
                d.lastRate = 0
                try {
                    root.setPointerCapture(e.pointerId)
                } catch {}
                if (!idleRaf) idleRaf = requestAnimationFrame(watchIdle)
                const handleMove = (ev: PointerEvent) => {
                    if (!d.isDragging) return
                    const now = performance.now()
                    const dxPx = ev.clientX - d.lastX
                    const dtReal = Math.max(
                        (now - d.lastMoveTime) / 1000,
                        1 / 240
                    )
                    const dOffset = dxPx * deltaTPerPx()
                    d.offset += dOffset
                    const rate = dOffset / dtReal
                    d.lastRate = rate
                    d.extraRate = rate
                    d.lastX = ev.clientX
                    d.lastMoveTime = now
                }
                const end = () => {
                    window.removeEventListener("pointermove", handleMove)
                    window.removeEventListener("pointerup", end)
                    window.removeEventListener("pointercancel", end)
                    window.removeEventListener("blur", end)
                    endInFlight = null
                    if (!d.isDragging) return
                    d.isDragging = false
                    try {
                        root.releasePointerCapture(e.pointerId)
                    } catch {}
                    handleRelease(d.lastRate)
                }
                endInFlight = end
                window.addEventListener("pointermove", handleMove)
                window.addEventListener("pointerup", end)
                window.addEventListener("pointercancel", end)
                window.addEventListener("blur", end)
            }
            root.addEventListener("pointerdown", onPointerDown)
            removeDown = () =>
                root.removeEventListener("pointerdown", onPointerDown)

            // scroll:水平(deltaX)only,passive —— 縱向頁面捲動永不被 preventDefault。
            const onWheel = (e: WheelEvent) => {
                if (e.deltaX === 0) return
                stopRelease()
                clearTimeout(wheelTimer as ReturnType<typeof setTimeout>)
                if (!d.isDragging) d.playing = false
                d.isDragging = true
                const dOffset = e.deltaX * deltaTPerPx()
                d.offset += dOffset
                const rate = dOffset / (1 / 60)
                d.extraRate = rate
                wheelTimer = setTimeout(() => {
                    d.isDragging = false
                    handleRelease(rate)
                }, 120)
            }
            root.addEventListener("wheel", onWheel, { passive: true })
            removeWheel = () => root.removeEventListener("wheel", onWheel)
        }

        return () => {
            cancelAnimationFrame(raf)
            stopRelease()
            if (idleRaf) cancelAnimationFrame(idleRaf)
            clearTimeout(wheelTimer as ReturnType<typeof setTimeout>)
            removeDown?.()
            removeWheel?.()
            endInFlight?.()
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isStatic, poolSize, draggable, paint])

    // ⚠️ 透視鏈忠實重建:frame(量測) → 設計方形畫布(contain 置中) →
    //    scene(容器級 perspective) → offset(preserve-3d) → group(preserve-3d,
    //    rotateX/Y/Z + zoom) → card。
    return (
        <div
            /* frame(量測外層寬高) */
            ref={rootRef}
            style={{
                position: "absolute",
                inset: 0 as any,
                overflow: "hidden",
                touchAction: draggable ? "pan-y" : "auto",
            }}
        >
            <div
                /* 設計方形畫布 DESIGN²:contain 縮放 + 置中。overflow:hidden 對齊 app
                   .preview-canvas 的 1080² 裁切面。 */
                style={{
                    position: "absolute",
                    left: "50%",
                    top: "50%",
                    width: DESIGN,
                    height: DESIGN,
                    overflow: "hidden",
                    transform: `translate(-50%, -50%) scale(${fitScale})`,
                    transformOrigin: "center",
                }}
            >
                <div
                    /* .tpl-scene —— 容器級 perspective(orbit 環狀 3D 的透視源) */
                    style={{
                        position: "absolute",
                        inset: 0 as any,
                        perspective: `${LOCKED.perspective}px`,
                    }}
                >
                    <div
                        /* .tpl-offset */
                        style={{
                            position: "absolute",
                            inset: 0 as any,
                            transformStyle: "preserve-3d",
                            transform: `translate(${LOCKED.offsetX}px, ${LOCKED.offsetY}px)`,
                        }}
                    >
                        <div
                            /* .tpl-group —— preserve-3d(非 flat);zoom 走 scale(zoom/100) */
                            style={{
                                position: "absolute",
                                inset: 0 as any,
                                transformStyle: "preserve-3d",
                                transform: `rotateX(${LOCKED.rotationX}deg) rotateY(${LOCKED.rotationY}deg) rotateZ(${LOCKED.rotationZ}deg) scale(${zoom / 100})`,
                            }}
                        >
                            {Array.from({ length: poolSize }).map((_, i) => (
                                <div
                                    /* .tpl-card */
                                    key={i}
                                    ref={(el) => {
                                        cardRefs.current[i] = el
                                    }}
                                    style={{
                                        position: "absolute",
                                        left: "50%",
                                        top: "50%",
                                        width: cardSize,
                                        height: cardHeight,
                                        borderRadius: cardRadius,
                                        overflow: "hidden",
                                        willChange: "transform, opacity",
                                    }}
                                >
                                    <img
                                        src={
                                            effectiveImages[
                                                i % effectiveImages.length
                                            ]
                                        }
                                        alt=""
                                        draggable={false}
                                        style={{
                                            width: "100%",
                                            height: "100%",
                                            objectFit: "cover",
                                            objectPosition: "center",
                                            display: "block",
                                            userSelect: "none",
                                        }}
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

// ----------------------------------------------------------------------
// Property controls —— Cards(圖片上傳)+ 7 個策展開放參數。
// 開放參數的 defaultValue = breathe-right preset 的值(拖進來即該效果);
// min/max = orbit schema.js 的已驗證安全值域。
// ----------------------------------------------------------------------
addPropertyControls(OrbitSpike, {
    // 真正的圖片上傳:Array of Image —— 買家可上傳/增刪/排序。
    images: {
        type: ControlType.Array,
        control: { type: ControlType.Image },
        title: "Cards",
        // 空 → 用內建預設示範圖(做法 B)。
    },
    // breathe-right count 16;schema 值域 3–30
    count: {
        type: ControlType.Number,
        title: "Count",
        min: 3,
        max: 30,
        step: 1,
        defaultValue: 16,
        displayStepper: true,
    },
    // breathe-right cardSize 230;schema 值域 120–1200
    cardSize: {
        type: ControlType.Number,
        title: "Card Size",
        min: 120,
        max: 1200,
        step: 1,
        defaultValue: 230,
        unit: "px",
    },
    // breathe-right cardRatio '3:4';schema enum
    cardRatio: {
        type: ControlType.Enum,
        title: "Card Ratio",
        options: ["1:1", "4:3", "3:4", "16:9", "9:16"],
        optionTitles: ["1:1", "4:3", "3:4", "16:9", "9:16"],
        defaultValue: "3:4",
        displaySegmentedControl: true,
    },
    // 策展:直接 px(相異處 #3)。預設 14 ≈ breathe-right 6% 的視覺等值。
    cornerRadius: {
        type: ControlType.Number,
        title: "Corner Radius",
        min: 0,
        max: 60,
        step: 1,
        defaultValue: 14,
        unit: "px",
        description: "Rounds the corners of every card. 0 = sharp corners.",
    },
    // breathe-right duration 30;schema 值域 2–60
    duration: {
        type: ControlType.Number,
        title: "Duration",
        min: 2,
        max: 60,
        step: 1,
        defaultValue: 30,
        unit: "s",
        description:
            "Seconds for one full revolution of the orbit. Higher is slower.",
    },
    // breathe-right zoom 130;schema 值域 50–300
    zoom: {
        type: ControlType.Number,
        title: "Zoom",
        min: 50,
        max: 300,
        step: 1,
        defaultValue: 130,
        unit: "%",
    },
    // 互動:拖曳/滾輪/慣性開關。預設 on;關掉回純自動播放。
    // 畫布靜止,拖曳只在 Preview / 發布後生效。
    draggable: {
        type: ControlType.Boolean,
        title: "Draggable",
        defaultValue: true,
        enabledTitle: "On",
        disabledTitle: "Off",
        description:
            "Drag, scroll, and flick with momentum (touch too). Off = autoplay only. Static on the canvas — dragging works in Preview and on the published site.",
    },
})
